package dashboard.enterprise.agent.llm.provider;
import dashboard.enterprise.agent.llm.model.*;import dashboard.enterprise.agent.model.AgentContext;import java.util.*;
public final class ReplayLlmProvider implements LlmProvider {private final String id;private final int priority;private final LlmModelConfiguration model;private final Set<String> capabilities;private final Map<String,Map<String,Object>> outputs;
 public ReplayLlmProvider(String id,int priority,Set<String> capabilities,Map<String,Map<String,Object>> outputs){this.id=id;this.priority=priority;this.capabilities=Set.copyOf(capabilities);this.outputs=Map.copyOf(outputs);this.model=new LlmModelConfiguration("mapaf.llm.model/v1","mapaf-replay-1",id,0,2048,1000,Map.of("mode","REPLAY"));}
 public String providerId(){return id;}public LlmProviderType providerType(){return LlmProviderType.REPLAY;}public int priority(){return priority;}public boolean available(){return true;}public Set<String> capabilities(){return capabilities;}public LlmModelConfiguration model(){return model;}
 public LlmResponse generate(AgentContext context,LlmRequest request){Map<String,Object> out=outputs.getOrDefault(request.capabilityId(),Map.of("result","replay"));int pt=Math.max(1,(request.systemPrompt().length()+request.userPrompt().length())/4);int ct=Math.max(1,out.toString().length()/4);LlmUsage usage=new LlmUsage("mapaf.llm.usage/v1",pt,ct,pt+ct,0);return new LlmResponse("mapaf.llm.response/v1",request.requestId(),id,model.modelId(),true,"Replay reasoning completed.",out.toString(),out,usage,List.of("llm:replay","provider:"+id));}}
